//! User-facing help needs no workspace, model, platform probe or toolchain.
const MAIN:&str="usage: justfit [--version] COMMAND\n\nCommands:\n  init DESTINATION    Create a new verified source workspace\n  verify              Verify bundled sources or a workspace\n  doctor              Check platform and optional Metal tools\n  build               Build the native runtime from a source workspace\n  serve               Start the local server; set up its workspace and runtime\n  model install       Install or select a verified model\n  runtime install     Install a pinned native runtime\n  ane install         Install matching precompiled ANE assets\n  replay TRACE        Replay an opt-in native crash trace\n\nUse justfit COMMAND --help for command options.";
const INIT:&str="usage: justfit init DESTINATION [--source PATH]\n\nCopy verified sources into a NEW writable workspace.";
const VERIFY:&str="usage: justfit verify [--project PATH]\n\nVerify bundled sources or an extracted workspace.";
const DOCTOR:&str="usage: justfit doctor [--metal-bin PATH]\n\nCheck the platform and, when supplied, the metal and metallib tools.";
const BUILD:&str="usage: justfit build [--project PATH] [--jobs N] [--metal-bin PATH] [--pdfium-library PATH]\n\nBuild the native runtime and vision helpers. Default jobs: 4.\nDefault workspace: ~/Library/Application Support/JustFit/2.6.0.\nSource builds require Rust/Cargo and Apple developer/Metal tools.";
const SERVE:&str="usage: justfit serve [OPTIONS]\n\n  --project PATH              Workspace, created on first use\n  --node m4|m5|m6             Preset; default from chip and memory\n  --model MODEL              Local model or Hub model ID\n  --revision REVISION        Model revision\n  --draft-model PATH         Source DFlash2 draft directory\n  --mmproj PATH              Local GGUF vision projector\n  --language-only            Prepare and serve text only\n  --offline                  Use cached models without contacting the Hub\n  --port PORT                Local HTTP port; default 8000\n  --state-dir PATH           Writable service state\n  --jobs N                    Source-build jobs; default 4\n  --metal-bin PATH           Source-build Metal tools\n  --runtime-bundle ZIP        Pinned local runtime\n  --runtime-manifest URL      Pinned HTTPS runtime manifest\n  --runtime-sha256 SHA        Pin for the chosen runtime source\n  --vision-profile PATH      Existing vision profile\n  --no-ane-vision             Use GPU vision\n  --ane-bundle ZIP            Precompiled tier ZIP; repeat for 4K and 8K\n  --ane-sha256 SHA            Matching tier ZIP pin; repeat with each ZIP\n  --ane-manifest URL          HTTPS index for compatible ANE tiers\n  --ane-manifest-sha256 SHA   ANE index pin\n  --host ADDRESS              HTTP bind address\n  --allowed-host HOST         Additional allowed Host (repeatable)\n  --allowed-origin ORIGIN     Browser origin (repeatable)\n  --api-key KEY               Require API authentication\n  --served-model-name NAME    API alias (repeatable)\n  --announce-served-name      Report first API alias\n  --max-context TOKENS        auto or tokens up to 256K\n  --max-memory SIZE           Metal budget or auto\n  --host-reserve SIZE         Host memory reserve\n  --kv-format int8|bf16|tq4   Target KV format\n  --idle-release DURATION     Idle weight release, or off\n  --max-cache-disk SIZE       SSD quota; 0 disables cache\n  --persistent-cache          Persist cached prefixes across restarts\n  --cache-dir PATH            Persistent prefix cache directory\n  --max-request-size SIZE     Maximum HTTP body size\n  --max-image-pixels N        Resized image pixel budget\n  --request-timeout DURATION  Queued/in-flight request deadline\n  --queue-size N              Admitted requests\n  --decode-share N            Nonnegative decode scheduling share\n  --default-reasoning-effort E Default reasoning effort\n  --disable-ane               Disable language ANE offload\n  --allow-idle-sleep          Allow automatic sleep during requests\n  --no-webui                  Disable the chat page\n  --dry-run                   Print the plan without setup or downloads\n\nDefault model: mlx-community/Qwen3.8-27B-4bit (original MLX checkpoint).\nDefault DFlash2 draft is downloaded and prepared automatically.\nA binary distribution installs its bundled runtime automatically.\nDefault workspace: ~/Library/Application Support/JustFit/2.6.0.";
const MODEL:&str="usage: justfit model install [--project PATH] [--model MODEL] [--revision REVISION]\n       justfit model prepare [--project PATH] --target PATH [--draft-model PATH] [--mmproj PATH] [--language-only]\n       justfit model verify PATH\n\nSelect or install a verified model. HF_HUB_OFFLINE selects local cached files.";
const RUNTIME:&str="usage: justfit runtime install --project PATH (--bundle ZIP | --manifest HTTPS_URL) --sha256 SHA\n\nVerify and install the matching native runtime.";
const ANE:&str="usage: justfit ane install [--project PATH] [--node m4|m5|m6] [--model MODEL] [--revision REVISION]\n       (--ane-bundle ZIP --ane-sha256 SHA ... | --ane-manifest URL --ane-manifest-sha256 SHA)\n\nBoth matching 4K and 8K tiers are required for the automatic vision profile.";
const REPLAY:&str="usage: justfit replay TRACE\n\nReplay an opt-in schema-1 native crash trace offline.\nThe trace supplies the engine command and recorded input frames.";
fn flag(value:&str)->bool{matches!(value,"--help"|"-h")}
pub fn text(args:&[String])->Option<&'static str>{
    match args{
        [arg] if flag(arg)=>Some(MAIN),
        [command,arg] if flag(arg)=>match command.as_str(){"init"=>Some(INIT),"verify"=>Some(VERIFY),"doctor"=>Some(DOCTOR),"build"=>Some(BUILD),"serve"=>Some(SERVE),"model"=>Some(MODEL),"runtime"=>Some(RUNTIME),"ane"=>Some(ANE),"replay"=>Some(REPLAY),_=>None},
        [group,sub,arg] if flag(arg)&&sub=="install"=>match group.as_str(){"model"=>Some(MODEL),"runtime"=>Some(RUNTIME),"ane"=>Some(ANE),_=>None},
        [group,sub,arg] if flag(arg)&&group=="model"&&matches!(sub.as_str(),"verify"|"prepare")=>Some(MODEL),
        _=>None,
    }
}
